\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}
\begin{tikzpicture}[
font=\boldmath, scale=1.2,
fixstyle/.style={very thick, lightgray, shorten <= 1pt, shorten >= 1pt, arrows={-Latex[scale=1]}}
]

